-- ES/DE/FR translations for the rest of Luxembourg's deep-dive content.
-- No penalty_rows table for Luxembourg (no fixed fine schedule found),
-- so unlike Belgium there are no penalty-row translations here.

INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon) SELECT id, 'es', 'Peppol de 4 esquinas (B2G vigente; B2B propuesto para 2028-2029)', 'Esta página de análisis refleja la orientación técnica disponible públicamente a agosto de 2026 y se proporciona a título informativo general, no como asesoramiento legal o fiscal. El mandato B2B propuesto sigue sujeto a la aprobación parlamentaria y podría cambiar — confirme los requisitos actuales directamente con la CTIE / eFacturation.lu o con el Punto de Acceso Peppol que haya elegido antes de construir una integración.', 'Luxemburgo construyó su programa de facturación electrónica en dos fases claramente diferenciadas: un mandato B2G basado en Peppol, implementado gradualmente según el tamaño de la empresa y completado en 2023, seguido de una propuesta de ampliación a las transacciones B2B nacionales utilizando la misma red, aún pendiente de aprobación parlamentaria.', 'Luxemburgo se apoya en el perfil Peppol estándar de la UE en lugar de crear un formato nacional propio, con un portal web gubernamental disponible como alternativa manual para los proveedores B2G más pequeños.', 'No existe una plataforma de compensación independiente en Luxemburgo — Peppol ha gestionado el tráfico B2G desde el principio, y el mandato B2B propuesto ampliaría la misma red de cuatro esquinas a las transacciones nacionales.', 'Cumplir con la normativa se centra en confirmar su identidad Peppol y su configuración de archivo — el portal guichet.lu / eFacturation.lu existe precisamente para que los proveedores más pequeños no se vean bloqueados por la falta de un software preparado para Peppol.', 'Luxemburgo no ha publicado una escala de sanciones fija para el incumplimiento en materia de facturación electrónica — la aplicación actual se basa en el rechazo de facturas y en consecuencias derivadas de la contratación pública, en lugar de sanciones automáticas.', 'El mandato de facturación electrónica B2G de Luxemburgo está plenamente vigente desde marzo de 2023, implementado por fases según el tamaño de la empresa bajo el estándar Peppol BIS Billing 3.0. Un proyecto de ley aprobado en julio de 2026 ampliaría la facturación electrónica obligatoria a las transacciones B2B nacionales en fases desde 2028 hasta 2029, aunque todavía no ha entrado en vigor.', '📜' FROM countries WHERE name_en = 'Luxembourg';
INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon) SELECT id, 'de', 'Peppol-4-Corner-Modell (B2G in Kraft; B2B für 2028-2029 vorgeschlagen)', 'Diese Länderanalyse spiegelt öffentlich verfügbare technische Hinweise mit Stand August 2026 wider und dient der allgemeinen Information, nicht als Rechts- oder Steuerberatung. Die vorgeschlagene B2B-Pflicht bedarf weiterhin der parlamentarischen Zustimmung und kann sich noch ändern — bestätigen Sie aktuelle Anforderungen direkt bei CTIE / eFacturation.lu oder Ihrem gewählten Peppol Access Point, bevor Sie eine Integration aufbauen.', 'Luxemburg hat sein E-Invoicing-Programm in zwei klar getrennten Phasen aufgebaut: eine Peppol-basierte B2G-Pflicht, die schrittweise nach Unternehmensgröße eingeführt und 2023 abgeschlossen wurde, gefolgt von einer vorgeschlagenen Ausweitung auf inländische B2B-Transaktionen über dasselbe Netzwerk, die noch der parlamentarischen Zustimmung bedarf.', 'Luxemburg setzt auf das Standard-Peppol-Profil der EU statt auf ein eigenes nationales Format, mit einem staatlichen Webportal als manueller Rückfalloption für kleinere B2G-Lieferanten.', 'Es gibt keine eigene luxemburgische Clearing-Plattform — Peppol hat den B2G-Verkehr von Anfang an abgewickelt, und die vorgeschlagene B2B-Pflicht würde dasselbe Vier-Ecken-Netzwerk auf inländische Transaktionen ausweiten.', 'Die Umsetzung dreht sich vor allem um die Bestätigung Ihrer Peppol-Identität und Ihrer Archivierungslösung — das Portal guichet.lu / eFacturation.lu existiert speziell dafür, dass kleinere Lieferanten nicht durch fehlende Peppol-fähige Software blockiert werden.', 'Luxemburg hat keine feste Bußgeldstaffel für Verstöße gegen die E-Invoicing-Pflicht veröffentlicht — die Durchsetzung erfolgt derzeit über die Ablehnung von Rechnungen und vergaberechtliche Konsequenzen, nicht über automatische Sanktionen.', 'Luxemburgs B2G-E-Invoicing-Pflicht ist seit März 2023 vollständig in Kraft und wurde stufenweise nach Unternehmensgröße unter dem Standard Peppol BIS Billing 3.0 eingeführt. Ein im Juli 2026 gebilligter Gesetzentwurf würde die verpflichtende E-Rechnung stufenweise von 2028 bis 2029 auf inländische B2B-Transaktionen ausweiten, ist aber noch nicht in Kraft.', '📜' FROM countries WHERE name_en = 'Luxembourg';
INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon) SELECT id, 'fr', 'Peppol à 4 coins (B2G en vigueur ; B2B proposé pour 2028-2029)', 'Cette analyse par pays reflète les directives techniques publiquement disponibles à août 2026 et est fournie à titre d''information générale, non comme un conseil juridique ou fiscal. L''obligation B2B proposée reste soumise à l''approbation parlementaire et pourrait évoluer — confirmez les exigences actuelles directement auprès du CTIE / eFacturation.lu ou de votre Access Point Peppol avant de construire une intégration.', 'Le Luxembourg a construit son programme de facturation électronique en deux phases distinctes : une obligation B2G fondée sur Peppol, déployée progressivement selon la taille de l''entreprise et achevée en 2023, suivie d''une extension proposée aux transactions B2B nationales via le même réseau, toujours en attente d''approbation parlementaire.', 'Le Luxembourg s''appuie sur le profil Peppol standard de l''UE plutôt que d''inventer un format national, avec un portail web gouvernemental disponible comme solution de repli manuelle pour les petits fournisseurs B2G.', 'Il n''existe pas de plateforme de contrôle luxembourgeoise distincte — Peppol gère le trafic B2G depuis le début, et l''obligation B2B proposée étendrait le même réseau à quatre coins aux transactions nationales.', 'La mise en conformité repose avant tout sur la confirmation de votre identité Peppol et de votre solution d''archivage — le portail guichet.lu / eFacturation.lu existe précisément pour que les petits fournisseurs ne soient pas bloqués faute de logiciel compatible Peppol.', 'Le Luxembourg n''a pas publié de barème d''amendes fixe pour le non-respect de la facturation électronique — l''application actuelle repose sur le rejet des factures et des conséquences liées aux marchés publics plutôt que sur des sanctions automatiques.', 'L''obligation de facturation électronique B2G au Luxembourg est pleinement en vigueur depuis mars 2023, déployée par étapes selon la taille de l''entreprise sous la norme Peppol BIS Billing 3.0. Un projet de loi approuvé en juillet 2026 étendrait la facturation électronique obligatoire aux transactions B2B nationales par phases de 2028 à 2029, bien qu''il ne soit pas encore en vigueur.', '📜' FROM countries WHERE name_en = 'Luxembourg';

