INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Formato y estándar', '[["Formato predeterminado", "Peppol BIS Billing 3.0 (UBL 2.1)"], ["Modelo semántico europeo", "EN 16931"], ["CIUS nacional", "Ninguno — utiliza directamente el CIUS de Peppol BIS"], ["Alternativa manual", "Formulario web guichet.lu / eFacturation.lu (introducción de datos estructurados o carga de archivos)"]]', 'Luxemburgo no exige un formato nacional propio para la facturación al sector público — el mismo perfil Peppol BIS Billing 3.0 utilizado en toda la UE cumple plenamente, y un portal web gubernamental cubre a los proveedores que todavía no cuentan con software conectado a Peppol.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Luxembourg' AND dc.section = 'file_format' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Format & Standard', '[["Standardformat", "Peppol BIS Billing 3.0 (UBL 2.1)"], ["Europäisches semantisches Modell", "EN 16931"], ["Nationale CIUS", "Keine — verwendet direkt die Peppol-BIS-CIUS"], ["Manuelle Alternative", "guichet.lu / eFacturation.lu-Webformular (strukturierte Dateneingabe oder Datei-Upload)"]]', 'Luxemburg verlangt kein eigenes nationales Format für die Rechnungsstellung an den öffentlichen Sektor — dasselbe in der gesamten EU verwendete Peppol-BIS-Billing-3.0-Profil ist voll konform, und ein staatliches Webportal deckt Lieferanten ab, die noch keine Peppol-fähige Software haben.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Luxembourg' AND dc.section = 'file_format' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Format et norme', '[["Format par défaut", "Peppol BIS Billing 3.0 (UBL 2.1)"], ["Modèle sémantique européen", "EN 16931"], ["CIUS national", "Aucun — utilise directement le CIUS Peppol BIS"], ["Alternative manuelle", "Formulaire web guichet.lu / eFacturation.lu (saisie structurée ou téléversement de fichier)"]]', 'Le Luxembourg n''exige pas de format national spécifique pour la facturation au secteur public — le même profil Peppol BIS Billing 3.0 utilisé dans toute l''UE est pleinement conforme, et un portail web gouvernemental couvre les fournisseurs qui ne disposent pas encore d''un logiciel compatible Peppol.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Luxembourg' AND dc.section = 'file_format' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Identificadores empresariales', '[["Esquema de ID Peppol", "9938 (número de IVA de Luxemburgo)"], ["Ejemplo de formato", "iso6523-actorid-upis::9938:LU + 8 dígitos"], ["Búsqueda en el directorio", "Directorio Peppol"]]', 'El esquema 9938 vincula su identidad Peppol directamente a su número de IVA de Luxemburgo, por lo que las empresas ya registradas a efectos del IVA no necesitan un identificador independiente para ser localizables en la red.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Luxembourg' AND dc.section = 'file_format' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Unternehmenskennungen', '[["Peppol-ID-Schema", "9938 (luxemburgische USt-IdNr.)"], ["Formatbeispiel", "iso6523-actorid-upis::9938:LU + 8 Ziffern"], ["Verzeichnissuche", "Peppol-Verzeichnis"]]', 'Schema 9938 verknüpft Ihre Peppol-Identität direkt mit Ihrer luxemburgischen USt-IdNr., sodass bereits umsatzsteuerlich registrierte Unternehmen keine separate ID benötigen, um im Netzwerk auffindbar zu sein.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Luxembourg' AND dc.section = 'file_format' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Identifiants d''entreprise', '[["Schéma d''identifiant Peppol", "9938 (numéro de TVA luxembourgeois)"], ["Exemple de format", "iso6523-actorid-upis::9938:LU + 8 chiffres"], ["Recherche dans l''annuaire", "Annuaire Peppol"]]', 'Le schéma 9938 relie directement votre identité Peppol à votre numéro de TVA luxembourgeois : les entreprises déjà immatriculées à la TVA n''ont donc pas besoin d''un identifiant distinct pour être visibles sur le réseau.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Luxembourg' AND dc.section = 'file_format' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Campos obligatorios de la factura', '[["Encabezado", "Número de factura único, fecha de emisión ISO 8601, moneda, referencia del contrato/pedido"], ["Datos de las partes", "Razón social, n.º de IVA, domicilio social, ID de participante Peppol"], ["Nivel de línea", "Código de categoría de IVA, tipo, cantidad, precio unitario, importe de línea"]]', 'Los organismos públicos pueden rechazar directamente las facturas electrónicas no conformes, por lo que los campos ausentes o incorrectos — en particular la referencia del contrato — son la causa más común de retraso en el pago, no las multas directas.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Luxembourg' AND dc.section = 'file_format' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Pflichtangaben der Rechnung', '[["Kopfdaten", "Eindeutige Rechnungsnummer, Ausstellungsdatum nach ISO 8601, Währung, Bestell-/Vertragsreferenz"], ["Parteidaten", "Firmenname, USt-IdNr., eingetragene Adresse, Peppol-Teilnehmer-ID"], ["Positionsebene", "USt-Kategoriecode, Satz, Menge, Einzelpreis, Positionssumme"]]', 'Öffentliche Stellen können nicht konforme E-Rechnungen direkt ablehnen, sodass fehlende oder falsche Angaben — insbesondere die Vertragsreferenz — die häufigste Ursache für Zahlungsverzögerungen sind, nicht direkte Bußgelder.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Luxembourg' AND dc.section = 'file_format' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Mentions obligatoires de la facture', '[["En-tête", "Numéro de facture unique, date d''émission ISO 8601, devise, référence de commande/contrat"], ["Données des parties", "Raison sociale, n° de TVA, adresse enregistrée, identifiant participant Peppol"], ["Niveau ligne", "Code de catégorie de TVA, taux, quantité, prix unitaire, total de ligne"]]', 'Les organismes publics peuvent rejeter directement les factures électroniques non conformes : les champs manquants ou erronés — en particulier la référence du contrat — sont donc la cause la plus fréquente de retard de paiement, plutôt que des amendes directes.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Luxembourg' AND dc.section = 'file_format' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Archivo', '[["Período de conservación", "10 años como mínimo"], ["Qué conservar", "Factura estructurada original + registros de transmisión/procesamiento"]]', 'El período de conservación de 10 años de Luxemburgo es más largo que en varios mercados vecinos — téngalo en cuenta en cualquier contrato con un Punto de Acceso Peppol, ya que necesitará acceso continuado a las facturas históricas mucho después de un posible cambio de proveedor.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Luxembourg' AND dc.section = 'file_format' AND dc.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Archivierung', '[["Aufbewahrungsfrist", "Mindestens 10 Jahre"], ["Was aufzubewahren ist", "Original der strukturierten Rechnung + Übermittlungs-/Verarbeitungsprotokolle"]]', 'Luxemburgs Aufbewahrungsfrist von 10 Jahren ist länger als in mehreren Nachbarmärkten — berücksichtigen Sie dies bei jedem Vertrag mit einem Peppol Access Point, da Sie auch nach einem möglichen Anbieterwechsel weiterhin Zugriff auf historische Rechnungen benötigen.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Luxembourg' AND dc.section = 'file_format' AND dc.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Archivage', '[["Durée de conservation", "10 ans minimum"], ["Éléments à conserver", "Facture structurée originale + journaux de transmission/traitement"]]', 'La durée de conservation de 10 ans au Luxembourg est plus longue que dans plusieurs marchés voisins — tenez-en compte dans tout contrat avec un Access Point Peppol, car vous aurez besoin d''un accès continu aux factures historiques bien après un éventuel changement de prestataire.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Luxembourg' AND dc.section = 'file_format' AND dc.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Modelo de red', '[["Modelo B2G", "Peppol de 4 esquinas (descentralizado)"], ["Canal manual", "Portal guichet.lu / eFacturation.lu"], ["Autoridad gubernamental", "CTIE (Centro de Informática del Gobierno) / eFacturation.lu"]]', 'A diferencia de otros países, Luxemburgo nunca construyó una plataforma central de compensación independiente para el B2G — Peppol ha sido la columna vertebral desde el principio, y el portal gubernamental existe solo como alternativa manual para los proveedores sin software preparado para Peppol.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Luxembourg' AND dc.section = 'scope_transmission' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Netzwerkmodell', '[["B2G-Modell", "Peppol 4-Corner (dezentral)"], ["Manueller Kanal", "Portal guichet.lu / eFacturation.lu"], ["Staatliche Behörde", "CTIE (staatliches IT-Zentrum) / eFacturation.lu"]]', 'Anders als einige Nachbarländer hat Luxemburg nie eine eigene zentrale Clearing-Plattform für B2G aufgebaut — Peppol war von Anfang an das Rückgrat, das staatliche Portal dient nur als manuelle Rückfalloption für Lieferanten ohne Peppol-fähige Software.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Luxembourg' AND dc.section = 'scope_transmission' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Modèle de réseau', '[["Modèle B2G", "Peppol à 4 coins (décentralisé)"], ["Canal manuel", "Portail guichet.lu / eFacturation.lu"], ["Autorité gouvernementale", "CTIE (Centre des technologies de l''information de l''État) / eFacturation.lu"]]', 'Contrairement à certains voisins, le Luxembourg n''a jamais mis en place de plateforme centrale de contrôle distincte pour le B2G — Peppol constitue l''épine dorsale depuis le début, le portail gouvernemental ne servant que de solution de repli manuelle pour les fournisseurs sans logiciel compatible Peppol.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Luxembourg' AND dc.section = 'scope_transmission' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Conectividad con el Punto de Acceso', '[["Requisito", "Punto de Acceso Peppol certificado (o entrada manual en guichet.lu)"], ["Proveedores habituales", "La mayoría de los ERP y plataformas contables compatibles con Peppol admiten Luxemburgo de forma nativa"], ["Punto de validación", "Las comprobaciones Schematron se ejecutan en el Punto de Acceso antes de entrar en la red"]]', 'Si es un proveedor pequeño con contratos públicos solo ocasionales, la vía manual de guichet.lu puede resultar más sencilla que incorporar un Punto de Acceso completo — reevalúelo cuando el volumen aumente.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Luxembourg' AND dc.section = 'scope_transmission' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Access-Point-Anbindung', '[["Anforderung", "Zertifizierter Peppol Access Point (oder manuelle Eingabe über guichet.lu)"], ["Gängige Anbieter", "Die meisten Peppol-fähigen ERP- und Buchhaltungsplattformen unterstützen Luxemburg standardmäßig"], ["Prüfpunkt", "Schematron-Prüfungen laufen am Access Point vor dem Eintritt ins Netzwerk"]]', 'Wenn Sie ein kleiner Lieferant mit nur gelegentlichen öffentlichen Aufträgen sind, kann der manuelle Weg über guichet.lu einfacher sein als die Einrichtung eines vollständigen Access Points — prüfen Sie dies neu, sobald das Volumen wächst.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Luxembourg' AND dc.section = 'scope_transmission' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Connectivité à l''Access Point', '[["Exigence", "Access Point Peppol certifié (ou saisie manuelle via guichet.lu)"], ["Fournisseurs courants", "La plupart des ERP et plateformes comptables compatibles Peppol prennent en charge le Luxembourg nativement"], ["Point de validation", "Les contrôles Schematron s''effectuent au niveau de l''Access Point avant l''entrée sur le réseau"]]', 'Si vous êtes un petit fournisseur avec seulement des marchés publics occasionnels, la voie manuelle via guichet.lu peut être plus simple que l''intégration d''un Access Point complet — réévaluez la situation lorsque le volume augmente.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Luxembourg' AND dc.section = 'scope_transmission' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Próximamente: mandato B2B propuesto', '[["Modelo", "Peppol de cuatro esquinas (misma red que el B2G)"], ["Alcance", "Transacciones B2B nacionales entre empresas establecidas en Luxemburgo"], ["Estado legal", "Proyecto de ley aprobado por el Consejo de Gobierno el 17 de julio de 2026 — todavía no en vigor"]]', 'Se trata todavía de una propuesta, no de una ley — siga su tramitación en el Parlamento antes de dar por definitiva cualquier fecha de 2028 o 2029.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Luxembourg' AND dc.section = 'scope_transmission' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Demnächst: vorgeschlagene B2B-Pflicht', '[["Modell", "Peppol-Vier-Ecken-Modell (dasselbe Netzwerk wie B2G)"], ["Geltungsbereich", "Inländische B2B-Transaktionen zwischen in Luxemburg ansässigen Unternehmen"], ["Rechtsstatus", "Gesetzentwurf vom Regierungsrat gebilligt am 17. Juli 2026 — noch nicht in Kraft"]]', 'Dies ist noch ein Vorschlag, kein Gesetz — verfolgen Sie den Fortschritt im Parlament, bevor Sie ein Datum in 2028/2029 als feststehend betrachten.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Luxembourg' AND dc.section = 'scope_transmission' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'À venir : obligation B2B proposée', '[["Modèle", "Peppol à quatre coins (même réseau que le B2G)"], ["Portée", "Transactions B2B nationales entre entreprises établies au Luxembourg"], ["Statut juridique", "Projet de loi approuvé par le Conseil de gouvernement le 17 juillet 2026 — pas encore en vigueur"]]', 'Il ne s''agit encore que d''une proposition, pas d''une loi — suivez son avancement au Parlement avant de considérer une date de 2028/2029 comme définitive.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Luxembourg' AND dc.section = 'scope_transmission' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', '⚖️ Sin escala de sanciones fija (B2G)', NULL, NULL, 'Las facturas B2G no conformes suelen ser rechazadas o devueltas sin pago por el organismo público receptor, en lugar de generar una multa automática — pero el incumplimiento persistente puede derivar en disputas contractuales o consecuencias administrativas conforme a la normativa de contratación pública.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Luxembourg' AND dc.section = 'penalties_related' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', '⚖️ Keine feste Bußgeldstaffel (B2G)', NULL, NULL, 'Nicht konforme B2G-Rechnungen werden von der empfangenden öffentlichen Stelle in der Regel abgelehnt oder unbezahlt zurückgesendet, statt automatisch ein Bußgeld auszulösen — anhaltende Nichteinhaltung kann jedoch zu Vertragsstreitigkeiten oder verwaltungsrechtlichen Konsequenzen nach dem Vergaberecht führen.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Luxembourg' AND dc.section = 'penalties_related' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', '⚖️ Pas de barème d''amendes fixe (B2G)', NULL, NULL, 'Les factures B2G non conformes sont généralement rejetées ou renvoyées impayées par l''organisme public destinataire plutôt que de déclencher une amende automatique — mais un non-respect persistant peut entraîner des litiges contractuels ou des conséquences administratives au titre du droit des marchés publics.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Luxembourg' AND dc.section = 'penalties_related' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', '🌍 No se prevé un reporte nacional en tiempo real', NULL, NULL, 'El impulso de Luxemburgo a la facturación electrónica se centra en el intercambio de facturas estructuradas, no en el reporte a la administración tributaria — actualmente no se prevé ningún control continuo de transacciones ni una capa de reporte electrónico a nivel nacional, a diferencia del despliegue de reporte electrónico de Bélgica previsto para 2028.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Luxembourg' AND dc.section = 'penalties_related' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', '🌍 Keine inländische Echtzeit-Meldung geplant', NULL, NULL, 'Luxemburgs E-Invoicing-Vorstoß zielt auf den strukturierten Rechnungsaustausch ab, nicht auf die Meldung an die Steuerbehörde — derzeit ist keine inländische kontinuierliche Transaktionskontrolle oder E-Reporting-Ebene geplant, anders als beim für 2028 geplanten E-Reporting-Ausbau in Belgien.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Luxembourg' AND dc.section = 'penalties_related' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', '🌍 Aucune déclaration nationale en temps réel prévue', NULL, NULL, 'L''élan du Luxembourg en matière de facturation électronique porte sur l''échange de factures structurées, pas sur la déclaration à l''administration fiscale — aucun contrôle continu des transactions ni couche de télédéclaration nationale n''est actuellement prévu, contrairement au déploiement du e-reporting belge prévu pour 2028.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Luxembourg' AND dc.section = 'penalties_related' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', '📋 El B2B sigue siendo un proyecto', NULL, NULL, 'La aprobación del Consejo de Gobierno en julio de 2026 es un paso real, pero el mandato B2B sigue sujeto a la aprobación parlamentaria antes de que las fechas de 2028/2029 entren en vigor.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Luxembourg' AND dc.section = 'penalties_related' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', '📋 B2B ist noch ein Entwurf', NULL, NULL, 'Die Billigung durch den Regierungsrat im Juli 2026 ist ein realer Schritt, doch die B2B-Pflicht bedarf weiterhin der parlamentarischen Zustimmung, bevor die Termine 2028/2029 in Kraft treten.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Luxembourg' AND dc.section = 'penalties_related' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', '📋 Le B2B reste un projet', NULL, NULL, 'L''approbation du Conseil de gouvernement en juillet 2026 constitue une étape réelle, mais l''obligation B2B reste soumise à l''approbation parlementaire avant que les échéances de 2028/2029 n''entrent en vigueur.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Luxembourg' AND dc.section = 'penalties_related' AND dc.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Confirme su número de IVA de Luxemburgo', 'Este número es también su identificador Peppol (esquema 9938) para la facturación B2G, así que compruebe que es correcto y está actualizado antes de registrarse con un Punto de Acceso.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Luxembourg' AND ds.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Bestätigen Sie Ihre luxemburgische USt-IdNr.', 'Diese ist zugleich Ihre Peppol-Kennung (Schema 9938) für die B2G-Rechnungsstellung — prüfen Sie daher, dass sie korrekt und aktuell ist, bevor Sie sich bei einem Access Point registrieren.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Luxembourg' AND ds.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Vérifiez votre numéro de TVA luxembourgeois', 'Ce numéro est également votre identifiant Peppol (schéma 9938) pour la facturation B2G — vérifiez qu''il est correct et à jour avant de vous enregistrer auprès d''un Access Point.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Luxembourg' AND ds.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Elija un Punto de Acceso Peppol certificado', 'Elija un proveedor independiente o confirme que su software de contabilidad/ERP actual ya incluye conectividad Peppol.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Luxembourg' AND ds.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Wählen Sie einen zertifizierten Peppol Access Point', 'Wählen Sie einen eigenständigen Anbieter oder bestätigen Sie, dass Ihre bestehende Buchhaltungs-/ERP-Software bereits über Peppol-Konnektivität verfügt.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Luxembourg' AND ds.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Choisissez un Access Point Peppol certifié', 'Choisissez un prestataire indépendant ou vérifiez que votre logiciel de comptabilité/ERP actuel inclut déjà la connectivité Peppol.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Luxembourg' AND ds.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Utilice guichet.lu / eFacturation.lu si aún no está preparado para Peppol', 'El formulario web gubernamental le permite introducir o cargar facturas B2G manualmente mientras configura una conectividad Peppol adecuada.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Luxembourg' AND ds.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Nutzen Sie guichet.lu / eFacturation.lu, falls Sie noch nicht Peppol-bereit sind', 'Über das staatliche Webformular können Sie B2G-Rechnungen manuell eingeben oder hochladen, während Sie eine ordentliche Peppol-Anbindung einrichten.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Luxembourg' AND ds.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Utilisez guichet.lu / eFacturation.lu si vous n''êtes pas encore prêt pour Peppol', 'Le formulaire web gouvernemental vous permet de saisir ou de téléverser manuellement des factures B2G pendant que vous mettez en place une connectivité Peppol adéquate.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Luxembourg' AND ds.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Pruebe la generación de facturas conforme a BIS Billing 3.0', 'Valide los códigos de categoría de IVA correctos, los números de factura únicos y la referencia del contrato del sector público — los errores en estos puntos son la causa más común de rechazo.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Luxembourg' AND ds.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Testen Sie die Rechnungserstellung gegen BIS Billing 3.0', 'Prüfen Sie korrekte USt-Kategoriecodes, eindeutige Rechnungsnummern und die Vertragsreferenz des öffentlichen Auftraggebers — Abweichungen hier sind die häufigste Ursache für Ablehnungen.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Luxembourg' AND ds.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Testez la génération des factures selon BIS Billing 3.0', 'Vérifiez les codes de catégorie de TVA corrects, les numéros de facture uniques et la référence du marché public — les erreurs à ce niveau sont la cause la plus fréquente de rejet.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Luxembourg' AND ds.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Configure un archivo conforme de 10 años', 'Confirme que su solución de conservación cumple el mínimo de 10 años de Luxemburgo, tanto para la factura estructurada original como para sus registros de transmisión/procesamiento.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Luxembourg' AND ds.sort_order = 4;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Richten Sie eine konforme 10-jährige Archivierung ein', 'Bestätigen Sie, dass Ihre Aufbewahrungslösung das luxemburgische Minimum von 10 Jahren sowohl für die ursprüngliche strukturierte Rechnung als auch für die Übermittlungs-/Verarbeitungsprotokolle erfüllt.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Luxembourg' AND ds.sort_order = 4;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Mettez en place un archivage conforme de 10 ans', 'Vérifiez que votre solution de conservation respecte le minimum luxembourgeois de 10 ans, tant pour la facture structurée originale que pour ses journaux de transmission/traitement.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Luxembourg' AND ds.sort_order = 4;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Si comercia B2B a nivel nacional, empiece a seguir el proyecto de ley', 'El plazo de recepción propuesto para 2028 utilizaría la misma infraestructura Peppol que el B2G — estar preparado para el B2G ahora le pone por delante.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Luxembourg' AND ds.sort_order = 5;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Falls Sie inländisch B2B handeln, verfolgen Sie den Gesetzentwurf', 'Die vorgeschlagene Empfangsfrist 2028 würde dieselbe Peppol-Infrastruktur wie B2G nutzen — wer jetzt B2G-bereit ist, liegt bereits vorn.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Luxembourg' AND ds.sort_order = 5;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Si vous commercez en B2B au niveau national, suivez le projet de loi', 'L''échéance de réception proposée pour 2028 utiliserait la même infrastructure Peppol que le B2G — être prêt pour le B2G dès maintenant vous met en avance.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Luxembourg' AND ds.sort_order = 5;

INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT dp.id, 'es', 'Bloques de Construcción Digital de la UE — Luxemburgo' FROM deep_dive_portals dp JOIN countries c ON c.id = dp.country_id WHERE c.name_en = 'Luxembourg' AND dp.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT dp.id, 'de', 'EU Digital Building Blocks — Luxemburg' FROM deep_dive_portals dp JOIN countries c ON c.id = dp.country_id WHERE c.name_en = 'Luxembourg' AND dp.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT dp.id, 'fr', 'Blocs de construction numériques de l''UE — Luxembourg' FROM deep_dive_portals dp JOIN countries c ON c.id = dp.country_id WHERE c.name_en = 'Luxembourg' AND dp.sort_order = 0;
